def stable_unique(values):
    seen = set()
    result = []
    for value in values:
        if value not in seen:
            seen.add(value)
            result.append(value)
    return result

def running_totals(values):
    total = 0
    result = []
    for value in values:
        total += value
        result.append(total)
    return result

